  "claim_id": "C016",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C016.component",
    "value": "The single small release slot should target the smallest change addressing a recurrent, independently corroborated and product-addressable retention point.",
    "scope": "A selection rule for an intervention when an actionable constraint is distinguishable; it does not assert that such a constraint has been found.",
    "provenance": {
      "refs": [
        {
          "source_id": "P010",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the selection rule, its evidence requirements and the measurement fallback."
    }
  },
  "signal_basis": {
    "component_id": "C016.signal_basis",
    "value": "Repeated trajectory observations reveal a recurrent retention point, with independent corroboration sufficient to distinguish a constraint that a product change can address.",
    "scope": "Evidence for selecting a targeted intervention to test; timing or inactivity alone does not establish a cause or demonstrate intervention benefit.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
